import{_ as t,c as a,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const m=JSON.parse('{"title":"Sample Data and Credits","description":"Where the images in this documentation come from, and how to cite them if you reuse them.","frontmatter":{"title":"Sample Data and Credits","description":"Where the images in this documentation come from, and how to cite them if you reuse them."},"headers":[],"relativePath":"sample-data.md","filePath":"sample-data.md"}'),n={name:"sample-data.md"};function s(i,e,l,h,c,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sample-data-and-credits" tabindex="-1">Sample Data and Credits <a class="header-anchor" href="#sample-data-and-credits" aria-label="Permalink to &quot;Sample Data and Credits&quot;">​</a></h1><p>Every screenshot in these guides uses public data. Nothing here is customer material.</p><p>If you reuse one of these images, cite the source rather than this site.</p><h2 id="whole-slide-h-e-cmu-1" tabindex="-1">Whole-slide H&amp;E, <code>CMU-1</code> <a class="header-anchor" href="#whole-slide-h-e-cmu-1" aria-label="Permalink to &quot;Whole-slide H&amp;E, `CMU-1`&quot;">​</a></h2><p>Used in the <a href="./guides/annotations.html">Annotations</a> and <a href="./guides/templates.html">Annotation Templates</a> guides, and for the brightfield display states in <a href="./guides/channels.html">Channels</a>.</p><p>A freely distributed test slide from the <a href="https://openslide.org/" target="_blank" rel="noreferrer">OpenSlide</a> project, converted to OME-Zarr with <code>bioformats2raw</code>. Widely used for testing whole-slide readers.</p><h2 id="high-content-screen-bbbc013" tabindex="-1">High-content screen, <code>BBBC013</code> <a class="header-anchor" href="#high-content-screen-bbbc013" aria-label="Permalink to &quot;High-content screen, `BBBC013`&quot;">​</a></h2><p>Used in <a href="./guides/analytics-phenotyping.html">Analytics &amp; Phenotyping</a>, parts of <a href="./guides/labels.html">Labels</a>, and for the fluorescence display states in <a href="./guides/channels.html">Channels</a>.</p><p>Human U2OS cells, cytoplasm-to-nucleus translocation, from the <a href="https://bbbc.broadinstitute.org/BBBC013" target="_blank" rel="noreferrer">Broad Bioimage Benchmark Collection</a>.</p><p>The collection asks that you cite:</p><blockquote><p>Ljosa V, Sokolnicki KL, Carpenter AE (2012). Annotated high-throughput microscopy image sets for validation. <em>Nature Methods</em> 9(7):637.</p></blockquote><p>The segmentation masks and measurements shown alongside it were produced by running StarDist and Cellpose over that image set. They are our output, not part of the original collection.</p><h2 id="fluorescence-nuclei-6001240" tabindex="-1">Fluorescence nuclei, <code>6001240</code> <a class="header-anchor" href="#fluorescence-nuclei-6001240" aria-label="Permalink to &quot;Fluorescence nuclei, `6001240`&quot;">​</a></h2><p>Used in <a href="./guides/labels.html">Labels</a>.</p><p>Image 6001240 from the <a href="https://idr.openmicroscopy.org/" target="_blank" rel="noreferrer">Image Data Resource</a>, study <code>idr0062</code>, served from IDR&#39;s public bucket. It is one of the most commonly used OME-Zarr samples, and the viewer&#39;s own <a href="https://find-nuclei.github.io/" target="_blank" rel="noreferrer">live examples</a> read it directly from IDR rather than re-hosting it.</p><h2 id="plate-76-45" tabindex="-1">Plate, <code>76-45</code> <a class="header-anchor" href="#plate-76-45" aria-label="Permalink to &quot;Plate, `76-45`&quot;">​</a></h2><p>Used in <a href="./guides/hcs-plates.html">HCS Plates</a> and for the channel controls in <a href="./guides/channels.html">Channels</a>.</p><p>Converted to OME-Zarr 0.5 for the <strong>OME 2024 NGFF Challenge</strong>, a community effort to publish a large body of public imaging in the current NGFF version. The store records the conversion tool but not the originating study, so we cannot name the original authors here. If you recognise it, please tell us and we will credit it properly.</p><h2 id="synthetic-rgb" tabindex="-1">Synthetic RGB <a class="header-anchor" href="#synthetic-rgb" aria-label="Permalink to &quot;Synthetic RGB&quot;">​</a></h2><p>Used for the RGB control in <a href="./guides/channels.html">Channels</a>.</p><p>Generated by us as a test fixture. Not real microscopy, and not something to cite.</p>',21)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
